control_functions.CHECKBOX:
if dtype == DataType.BOOLEAN:
    # Таблица 4.4 — бинарный выбор
    p, o, r = 0.99, 0.97, 0.96
else:
    p, o, r = 0.50, 0.50, 0.50

control_functions.SPINNER:
if dtype == DataType.UNSIGNED:
    # Двунаправленный счётчик: высокая эффективность при малом диапазоне Δ
    if size <= 3:
        p, o, r = 0.96, 0.90, 0.91
    elif size <= 7:
        p, o, r = 0.88, 0.65, 0.72
    else:
        p, o, r = 0.75, 0.35, 0.50
else:
    p, o, r = 0.50, 0.50, 0.50

control_functions.SLIDER:
if dtype == DataType.UNSIGNED:
    # Ползунок: стабильно высокая оперативность на средних и больших диапазонах
    if size <= 5:
        p, o, r = 0.92, 0.93, 0.90
    elif size <= 15:
        p, o, r = 0.88, 0.90, 0.82
    else:
        p, o, r = 0.84, 0.85, 0.75
else:
    p, o, r = 0.50, 0.50, 0.50

control_functions.TEXTBOX_RO:
if dtype == DataType.TEXT:
    # Статический вывод (восприятие информации)
    p, o, r = 0.99, 0.95, 0.95
else:
    p, o, r = 0.50, 0.50, 0.50
